package com.familyguard.parent;
import android.app.Activity;import android.app.Notification;import android.app.NotificationChannel;import android.app.NotificationManager;import android.os.Build;import android.content.pm.PackageManager;import android.os.Bundle;import android.graphics.Typeface;import android.widget.*;import android.content.Intent;import android.net.Uri;
import com.google.firebase.FirebaseApp;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;import java.security.SecureRandom;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout root,requests,devices;TextView status,codeView;FirebaseAuth auth;FirebaseFirestore db;ListenerRegistration requestListener,deviceListener;final Map<String,ListenerRegistration> locationListeners=new HashMap<>();final Map<String,ListenerRegistration> geofenceListeners=new HashMap<>();final Set<String> initializedGeofenceFeeds=new HashSet<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},700);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,40,32,24);root.setBackgroundColor(0xFFF5F7FB);TextView title=new TextView(this);title.setText("FamilyGuard Parent");title.setTextSize(27);title.setTypeface(null,Typeface.BOLD);TextView intro=new TextView(this);intro.setText("Pair a Child device and review its shared location and history.");Button gen=new Button(this);gen.setText("Generate pairing code");gen.setOnClickListener(v->generateCode());codeView=new TextView(this);codeView.setText("No active code");codeView.setTextSize(22);status=new TextView(this);status.setText("Connecting to Firebase...");TextView dh=new TextView(this);dh.setText("Paired devices / latest location");dh.setTextSize(20);devices=new LinearLayout(this);devices.setOrientation(1);TextView rh=new TextView(this);rh.setText("Pending permission requests");rh.setTextSize(20);requests=new LinearLayout(this);requests.setOrientation(1);root.addView(title);root.addView(intro);root.addView(gen);root.addView(codeView);root.addView(status);root.addView(dh);root.addView(devices);root.addView(rh);root.addView(requests);setContentView(root);try{FirebaseApp.initializeApp(this);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();auth.signInAnonymously().addOnSuccessListener(x->{status.setText("Parent connected. Generate a code to pair Child.");watchRequests();watchDevices();}).addOnFailureListener(e->status.setText("Sign-in failed: "+e.getMessage()));}catch(Exception e){status.setText("Firebase setup error: "+e.getMessage());}}
 void generateCode(){if(auth.getUid()==null)return;String chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";SecureRandom r=new SecureRandom();StringBuilder s=new StringBuilder();for(int i=0;i<8;i++)s.append(chars.charAt(r.nextInt(chars.length())));String c=s.toString();Map<String,Object>d=new HashMap<>();d.put("parentUid",auth.getUid());d.put("createdAt",FieldValue.serverTimestamp());d.put("expiresAt",new Date(System.currentTimeMillis()+50L*60L*1000L));d.put("consumedBy","");db.collection("pairCodes").document(c).set(d).addOnSuccessListener(x->{codeView.setText("PAIRING CODE\n"+c+"\nExpires in 50 minutes");status.setText("Enter this code on the Child phone.");}).addOnFailureListener(e->status.setText("Code error: "+e.getMessage()));}
 void watchRequests(){if(requestListener!=null)requestListener.remove();requestListener=db.collection("approvalRequests").whereEqualTo("parentUid",auth.getUid()).whereEqualTo("status","pending").addSnapshotListener((snap,e)->{if(e!=null){status.setText("Sync error: "+e.getMessage());return;}requests.removeAllViews();if(snap==null||snap.isEmpty()){TextView t=new TextView(this);t.setText("No pending requests.");requests.addView(t);return;}for(DocumentSnapshot d:snap){TextView label=new TextView(this);label.setText((d.getString("childLabel")==null?"Child":d.getString("childLabel"))+" requests "+d.getString("permission"));LinearLayout row=new LinearLayout(this);Button yes=new Button(this),no=new Button(this);yes.setText("Approve");no.setText("Deny");yes.setOnClickListener(v->resolve(d.getId(),"approved"));no.setOnClickListener(v->resolve(d.getId(),"denied"));row.addView(yes,new LinearLayout.LayoutParams(0,-2,1));row.addView(no,new LinearLayout.LayoutParams(0,-2,1));requests.addView(label);requests.addView(row);}});}
 void watchDevices(){if(deviceListener!=null)deviceListener.remove();deviceListener=db.collection("familyLinks").whereEqualTo("parentUid",auth.getUid()).addSnapshotListener((snap,e)->{if(e!=null){status.setText("Device sync error: "+e.getMessage());return;}devices.removeAllViews();if(snap==null||snap.isEmpty()){TextView t=new TextView(this);t.setText("No Child device paired yet.");devices.addView(t);return;}Set<String> active=new HashSet<>();for(DocumentSnapshot d:snap){String child=d.getString("childUid");if(child==null)continue;active.add(child);String label=d.getString("childLabel")==null?"Child":d.getString("childLabel");TextView item=new TextView(this);item.setText("Device: "+label+"\nWaiting for location…");devices.addView(item);Button map=new Button(this);map.setText("Open latest location in Maps");map.setEnabled(false);devices.addView(map);EditText fenceInput=new EditText(this);fenceInput.setSingleLine(true);fenceInput.setHint("Geofence: latitude,longitude,radius(m)");devices.addView(fenceInput);Button addFence=new Button(this);addFence.setText("Add safe-zone geofence");TextView fenceEvents=new TextView(this);fenceEvents.setText("No geofence events loaded.");devices.addView(addFence);devices.addView(fenceEvents);addFence.setOnClickListener(v->addGeofence(child,fenceInput,fenceEvents));watchGeofenceEvents(child,fenceEvents);Button history=new Button(this);history.setText("View location history");TextView historyView=new TextView(this);historyView.setText("Location history is not loaded.");devices.addView(history);devices.addView(historyView);history.setOnClickListener(v->loadHistory(child,historyView));Button usage=new Button(this);usage.setText("View last 24-hour usage report");TextView usageView=new TextView(this);usageView.setText("Usage report is not loaded.");devices.addView(usage);devices.addView(usageView);usage.setOnClickListener(v->loadUsageReport(child,usageView));EditText blockPackage=new EditText(this);blockPackage.setSingleLine(true);blockPackage.setHint("App package name (e.g. com.example.app)");devices.addView(blockPackage);Button blockApp=new Button(this);blockApp.setText("Block this app on Child device");TextView blockStatus=new TextView(this);devices.addView(blockApp);devices.addView(blockStatus);blockApp.setOnClickListener(v->addAppBlockRule(child,blockPackage,blockStatus));Button unblockApp=new Button(this);unblockApp.setText("Remove app block for this package");devices.addView(unblockApp);unblockApp.setOnClickListener(v->removeAppBlockRule(child,blockPackage,blockStatus));EditText limitPackage=new EditText(this);limitPackage.setSingleLine(true);limitPackage.setHint("Screen-time app package name");devices.addView(limitPackage);EditText limitMinutes=new EditText(this);limitMinutes.setSingleLine(true);limitMinutes.setInputType(2);limitMinutes.setHint("Daily limit in minutes (1–1440)");devices.addView(limitMinutes);Button saveLimit=new Button(this);saveLimit.setText("Set daily screen-time limit");TextView limitStatus=new TextView(this);devices.addView(saveLimit);devices.addView(limitStatus);saveLimit.setOnClickListener(v->saveScreenTimeLimit(child,limitPackage,limitMinutes,limitStatus));Button removeLimit=new Button(this);removeLimit.setText("Remove screen-time limit");devices.addView(removeLimit);removeLimit.setOnClickListener(v->removeScreenTimeLimit(child,limitPackage,limitStatus));EditText websiteDomain=new EditText(this);websiteDomain.setSingleLine(true);websiteDomain.setHint("Website domain (e.g. example.com)");devices.addView(websiteDomain);Button blockWebsite=new Button(this);blockWebsite.setText("Block website domain");TextView websiteStatus=new TextView(this);devices.addView(blockWebsite);devices.addView(websiteStatus);blockWebsite.setOnClickListener(v->addWebsiteBlock(child,websiteDomain,websiteStatus));Button unblockWebsite=new Button(this);unblockWebsite.setText("Remove website block");devices.addView(unblockWebsite);unblockWebsite.setOnClickListener(v->removeWebsiteBlock(child,websiteDomain,websiteStatus));Button browserReport=new Button(this);browserReport.setText("View recent browser domain activity");TextView browserView=new TextView(this);browserView.setText("Browser domain activity is not loaded.");devices.addView(browserReport);devices.addView(browserView);browserReport.setOnClickListener(v->loadBrowserDomainEvents(child,browserView));ListenerRegistration old=locationListeners.get(child);if(old!=null)old.remove();ListenerRegistration lr=db.collection("locations").document(child).addSnapshotListener((loc,le)->{if(le!=null){item.setText("Device: "+label+"\nLocation error: "+le.getMessage());return;}if(loc==null||!loc.exists()){item.setText("Device: "+label+"\nWaiting for Child to start location sharing.");return;}Double lat=loc.getDouble("latitude"),lon=loc.getDouble("longitude"),acc=loc.getDouble("accuracyMeters");String a=acc==null?"":String.format(Locale.US," (±%.0f m)",acc);item.setText("Device: "+label+"\nLatitude: "+lat+"\nLongitude: "+lon+a+"\nUpdated: "+loc.getTimestamp("capturedAt"));if(lat!=null&&lon!=null){map.setEnabled(true);map.setOnClickListener(v->{Uri u=Uri.parse("geo:"+lat+","+lon+"?q="+lat+","+lon+"("+Uri.encode(label)+")");startActivity(new Intent(Intent.ACTION_VIEW,u));});}});locationListeners.put(child,lr);}for(String id:new HashSet<>(locationListeners.keySet()))if(!active.contains(id)){locationListeners.get(id).remove();locationListeners.remove(id);}});}
 void watchGeofenceEvents(String child,TextView output){if(geofenceListeners.containsKey(child))return;ListenerRegistration reg=db.collection("geofenceEvents").whereEqualTo("parentUid",auth.getUid()).whereEqualTo("childUid",child).limit(20).addSnapshotListener((events,e)->{if(e!=null){output.setText("Geofence event error: "+e.getMessage());return;}boolean first=initializedGeofenceFeeds.add(child);if(events==null||events.isEmpty()){output.setText("No geofence entry/exit alerts yet.");return;}StringBuilder b=new StringBuilder("Geofence alerts:\n");for(DocumentSnapshot ev:events){String label=ev.getString("label"),type=ev.getString("eventType");b.append(label==null?"Safe zone":label).append(": ").append(type==null?"event":type).append("\n");}output.setText(b.toString());if(!first){for(DocumentChange change:events.getDocumentChanges())if(change.getType()==DocumentChange.Type.ADDED)showGeofenceNotification(child,change.getDocument());}});geofenceListeners.put(child,reg);}
 void showGeofenceNotification(String child,DocumentSnapshot event){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return;String channel="familyguard_parent_alerts";NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(nm==null)return;if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(channel,"FamilyGuard alerts",NotificationManager.IMPORTANCE_DEFAULT));String label=event.getString("label")==null?"Safe zone":event.getString("label");String type=event.getString("eventType")==null?"changed":event.getString("eventType");Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,channel):new Notification.Builder(this);Notification n=b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("FamilyGuard: "+label).setContentText("Child "+type+" the safe zone").setAutoCancel(true).build();nm.notify((child+event.getId()).hashCode(),n);}
 void addGeofence(String child,EditText input,TextView output){try{String[] parts=input.getText().toString().trim().split(",");if(parts.length!=3)throw new IllegalArgumentException("Enter latitude,longitude,radius in metres.");double lat=Double.parseDouble(parts[0].trim()),lon=Double.parseDouble(parts[1].trim()),radius=Double.parseDouble(parts[2].trim());if(lat < -90||lat > 90||lon < -180||lon > 180||radius < 25||radius > 100000)throw new IllegalArgumentException("Coordinates invalid; radius must be 25–100000 metres.");Map<String,Object> data=new HashMap<>();data.put("parentUid",auth.getUid());data.put("childUid",child);data.put("label","Safe zone");data.put("latitude",lat);data.put("longitude",lon);data.put("radiusMeters",radius);data.put("active",true);data.put("createdAt",FieldValue.serverTimestamp());db.collection("geofences").add(data).addOnSuccessListener(ref->{output.setText("Safe zone saved. Child must keep visible location sharing active.");input.setText("");}).addOnFailureListener(e->output.setText("Geofence save failed: "+e.getMessage()));}catch(Exception e){output.setText("Invalid geofence: "+e.getMessage());}}
 void loadHistory(String child,TextView output){output.setText("Loading location history…");db.collection("locationHistory").whereEqualTo("childUid",child).orderBy("deviceTime",Query.Direction.DESCENDING).limit(10).get().addOnSuccessListener(s->{if(s.isEmpty()){output.setText("No location history yet. Child must start visible location sharing.");return;}StringBuilder b=new StringBuilder("Recent location history (up to 10):\n");for(DocumentSnapshot d:s){Double lat=d.getDouble("latitude"),lon=d.getDouble("longitude");Number time=d.get("deviceTime",Number.class);b.append("Lat: ").append(lat).append("  Lon: ").append(lon);if(time!=null)b.append("\nTime: ").append(new Date(time.longValue()));b.append("\n\n");}output.setText(b.toString());}).addOnFailureListener(e->output.setText("History error: "+e.getMessage()));}

 void loadUsageReport(String child,TextView output){output.setText("Loading usage report…");db.collection("usageReports").document(child).get().addOnSuccessListener(d->{if(!d.exists()){output.setText("No usage report yet. Child must approve Usage Access in Android Settings and tap Share usage report now.");return;}List<Map<String,Object>> apps=(List<Map<String,Object>>)d.get("apps");if(apps==null||apps.isEmpty()){output.setText("No app usage data was reported for the last 24 hours.");return;}StringBuilder b=new StringBuilder("Last 24 hours app usage (reported by Child):\n");for(Map<String,Object> app:apps){String pkg=(String)app.get("packageName");Object millis=app.get("foregroundMillis");long ms=millis instanceof Number?((Number)millis).longValue():0;b.append(pkg==null?"Unknown app":pkg).append(" — ").append(String.format(Locale.US,"%d h %02d min",ms/3600000,(ms/60000)%60)).append("\n");}output.setText(b.toString());}).addOnFailureListener(e->output.setText("Usage report error: "+e.getMessage()));}

 void addAppBlockRule(String child,EditText input,TextView output){String pkg=input.getText().toString().trim();if(!pkg.matches("[A-Za-z0-9_]+(\\.[A-Za-z0-9_]+)+")){output.setText("Enter a valid Android package name, e.g. com.example.app");return;}Map<String,Object> data=new HashMap<>();data.put("parentUid",auth.getUid());data.put("childUid",child);data.put("packageName",pkg);data.put("active",true);data.put("createdAt",FieldValue.serverTimestamp());db.collection("appBlockRules").add(data).addOnSuccessListener(ref->{output.setText("Block rule saved. Child must enable FamilyGuard app restrictions in Android Accessibility Settings.");input.setText("");}).addOnFailureListener(e->output.setText("Could not save app block rule: "+e.getMessage()));}

 void removeAppBlockRule(String child,EditText input,TextView output){String pkg=input.getText().toString().trim();if(pkg.isEmpty()){output.setText("Enter the package name to remove.");return;}db.collection("appBlockRules").whereEqualTo("childUid",child).get().addOnSuccessListener(s->{WriteBatch batch=db.batch();int removed=0;for(DocumentSnapshot d:s){if(pkg.equals(d.getString("packageName"))){batch.delete(d.getReference());removed++;}}if(removed==0){output.setText("No matching app block rule.");return;}batch.commit().addOnSuccessListener(v->output.setText("App block rule removed.")).addOnFailureListener(e->output.setText("Remove failed: "+e.getMessage()));}).addOnFailureListener(e->output.setText("Lookup failed: "+e.getMessage()));}

 void saveScreenTimeLimit(String child,EditText pkgInput,EditText minutesInput,TextView output){String pkg=pkgInput.getText().toString().trim();String raw=minutesInput.getText().toString().trim();if(!pkg.matches("[A-Za-z0-9_]+(\\.[A-Za-z0-9_]+)+")){output.setText("Enter a valid Android package name.");return;}try{int minutes=Integer.parseInt(raw);if(minutes<1||minutes>1440)throw new NumberFormatException();Map<String,Object> data=new HashMap<>();data.put("parentUid",auth.getUid());data.put("childUid",child);data.put("packageName",pkg);data.put("dailyLimitMinutes",minutes);data.put("active",true);data.put("updatedAt",FieldValue.serverTimestamp());db.collection("screenTimeLimits").document(child+"_"+pkg).set(data).addOnSuccessListener(v->output.setText("Daily limit saved: "+minutes+" minutes. Child must enable Usage Access and FamilyGuard Accessibility service.")).addOnFailureListener(e->output.setText("Could not save limit: "+e.getMessage()));}catch(Exception e){output.setText("Enter a daily limit from 1 to 1440 minutes.");}}
 void removeScreenTimeLimit(String child,EditText pkgInput,TextView output){String pkg=pkgInput.getText().toString().trim();if(!pkg.matches("[A-Za-z0-9_]+(\\.[A-Za-z0-9_]+)+")){output.setText("Enter the package name to remove.");return;}db.collection("screenTimeLimits").document(child+"_"+pkg).delete().addOnSuccessListener(v->output.setText("Screen-time limit removed.")).addOnFailureListener(e->output.setText("Remove failed: "+e.getMessage()));}

 void loadBrowserDomainEvents(String child,TextView output){output.setText("Loading browser domain activity…");db.collection("browserDomainEvents").whereEqualTo("childUid",child).limit(30).get().addOnSuccessListener(s->{if(s.isEmpty()){output.setText("No DNS domain records yet. Child must enable Website Filtering VPN and use a DNS request path visible to it.");return;}List<DocumentSnapshot> rows=new ArrayList<>(s.getDocuments());rows.sort((a,b)->{com.google.firebase.Timestamp ta=a.getTimestamp("queriedAt"),tb=b.getTimestamp("queriedAt");long x=ta==null?0:ta.toDate().getTime(),y=tb==null?0:tb.toDate().getTime();return Long.compare(y,x);});StringBuilder text=new StringBuilder("Recent DNS domain activity (up to 30; domain only):\n");for(DocumentSnapshot d:rows){String domain=d.getString("domain");Boolean blocked=d.getBoolean("blocked");com.google.firebase.Timestamp t=d.getTimestamp("queriedAt");text.append(domain==null?"Unknown domain":domain).append(blocked!=null&&blocked?" — BLOCKED":" — queried");if(t!=null)text.append(" — ").append(t.toDate());text.append("\n");}output.setText(text.toString());}).addOnFailureListener(e->output.setText("Browser activity error: "+e.getMessage()));}
 String normalizeWebsiteDomain(String input){String d=input.trim().toLowerCase(Locale.US);if(d.startsWith("https://"))d=d.substring(8);if(d.startsWith("http://"))d=d.substring(7);if(d.startsWith("www."))d=d.substring(4);int slash=d.indexOf('/');if(slash>=0)d=d.substring(0,slash);return d;}
 void addWebsiteBlock(String child,EditText input,TextView output){String domain=normalizeWebsiteDomain(input.getText().toString());if(domain.length()>253||!domain.matches("(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}")){output.setText("Enter a valid domain, e.g. example.com (no wildcard).");return;}Map<String,Object> data=new HashMap<>();data.put("parentUid",auth.getUid());data.put("childUid",child);data.put("domain",domain);data.put("active",true);data.put("createdAt",FieldValue.serverTimestamp());db.collection("websiteBlockRules").document(child+"_"+domain.replace(".","_")).set(data).addOnSuccessListener(v->{output.setText("Domain block saved. Child must approve VPN and enable website filtering.");input.setText("");}).addOnFailureListener(e->output.setText("Could not save website rule: "+e.getMessage()));}
 void removeWebsiteBlock(String child,EditText input,TextView output){String domain=normalizeWebsiteDomain(input.getText().toString());if(domain.isEmpty()){output.setText("Enter the domain to remove.");return;}db.collection("websiteBlockRules").document(child+"_"+domain.replace(".","_")).delete().addOnSuccessListener(v->output.setText("Website block removed.")).addOnFailureListener(e->output.setText("Remove failed: "+e.getMessage()));}
 void resolve(String id,String v){db.collection("approvalRequests").document(id).update("status",v,"resolvedAt",FieldValue.serverTimestamp()).addOnFailureListener(e->status.setText("Update failed: "+e.getMessage()));}
 @Override protected void onDestroy(){if(requestListener!=null)requestListener.remove();if(deviceListener!=null)deviceListener.remove();for(ListenerRegistration r:locationListeners.values())r.remove();for(ListenerRegistration r:geofenceListeners.values())r.remove();super.onDestroy();}
}